/**
 * First line of a generated TypeScript file.
 */
export const GENERATED_HEADER =
  '// Generated by @rosen-bridge/config from the schema. Do not edit.';

/**
 * The hash algorithm of the schema hash (`SchemaDocument.hash`), whose value
 * starts with its name (`sha256:3f1c…`).
 */
export const HASH_ALGORITHM = 'sha256';

/**
 * The name the root type has in the declarations the schema hash is
 * computed from, so the hash does not depend on the name given to
 * `generateTypes`.
 */
export const HASH_ROOT_NAME = 'Config';

/**
 * The name of the constant a generated TypeScript file exports with the
 * schema hash.
 */
export const HASH_CONSTANT = 'SCHEMA_HASH';

/**
 * The declaration of `HASH_CONSTANT` in a generated TypeScript file, with
 * the hash as its first group.
 */
export const HASH_PATTERN = new RegExp(
  `^export const ${HASH_CONSTANT} = '([^']*)';$`,
  'm',
);

/**
 * The doc comment of `HASH_CONSTANT` in a generated TypeScript file.
 */
export const HASH_DOCUMENTATION = [
  '/**',
  ' * Hash of the schema these types were generated from: pass it to',
  ' * `validate` to detect a schema changed since.',
  ' */',
].join('\n');
